<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import type { TrainingRecord } from '../../../shared/fitness'
import { trainingFrequency, type FrequencyGroup } from './trainingFrequency'
import FitnessChart from './FitnessChart.vue'
const props=defineProps<{records:TrainingRecord[];from:string;to:string;planStart:string;cycleLength:number}>()
const group=ref<FrequencyGroup>('week'),metric=ref<'sessions'|'days'>('sessions'),selected=ref(0)
const buckets=computed(()=>trainingFrequency(props.records,props.from,props.to,group.value,props.planStart,props.cycleLength))
const days=(records:TrainingRecord[])=>new Set(records.map(r=>r.date)).size
const unit=computed(()=>metric.value==='sessions'?'次':'天'),metricName=computed(()=>metric.value==='sessions'?'训练次数':'训练天数')
const active=computed(()=>buckets.value[selected.value])
const rule=computed(()=>({day:'每天分别统计',week:'自然周：周一至周日',month:'自然月：每月1日至月末',cycle:`按计划起始日 ${props.planStart}，每 ${props.cycleLength} 天一周期`}[group.value]))
watch(buckets,bs=>{selected.value=Math.max(0,bs.reduce((last,b,i)=>b.records.length?i:last,0))},{immediate:true})
const detailRecords=computed(()=>[...(active.value?.records||[])].sort((a,b)=>a.date.localeCompare(b.date)))
</script>
<template><section class="fit-card frequency-card"><header><div><h2>训练频率</h2><p class="fit-muted">查看训练在各个时段的分布，点选柱子可查看记录。</p></div><label class="frequency-group">统计周期<select v-model="group"><option value="day">每天</option><option value="week">每周</option><option value="month">每月</option><option value="cycle">每个训练周期</option></select></label></header><div class="frequency-toolbar"><div class="frequency-metric" aria-label="统计指标"><button :class="{active:metric==='sessions'}" :aria-pressed="metric==='sessions'" @click="metric='sessions'">训练次数</button><button :class="{active:metric==='days'}" :aria-pressed="metric==='days'" @click="metric='days'">训练天数</button></div><span>所选日期内：<b>{{ records.length }}</b> 次训练 · <b>{{ days(records) }}</b> 个训练日</span></div><p class="frequency-rule">{{ rule }}；首尾时段只统计所选日期内的记录。</p><div v-if="from&&to&&from<=to" class="frequency-chart-scroll"><div :style="{minWidth:Math.max(380,buckets.length*95)+'px'}"><FitnessChart :labels="buckets.map(b=>b.label)" :tooltip-labels="buckets.map(b=>b.title)" :values="buckets.map(b=>metric==='sessions'?b.records.length:days(b.records))" :tooltip-details="buckets.map(b=>[metric==='sessions'?'训练日：'+days(b.records)+' 天':'训练记录：'+b.records.length+' 次',b.records.length?[...new Set(b.records.map(r=>r.type))].map(t=>t+' '+b.records.filter(r=>r.type===t).length+'次').join(' · '):'没有训练记录'])" :value-label="metricName" :unit="unit" bars integer show-values :selected-index="selected" @select="selected=$event"/></div></div><p v-else class="fit-empty">请选择有效的起止日期。</p><div v-if="active" class="frequency-detail"><div class="frequency-detail-head"><div><b>{{ active.start }} — {{ active.end }}</b><span>{{ active.records.length }} 次训练 · {{ days(active.records) }} 个训练日</span></div><small>已选时段</small></div><div v-if="detailRecords.length" class="frequency-records"><div v-for="r in detailRecords" :key="r.id"><time>{{ r.date.slice(5).replace('-','.') }}</time><span>{{ r.title }}</span><small>{{ r.minutes===null?'未填用时':r.minutes+' 分钟' }}</small></div></div><p v-else class="fit-muted">该时段没有训练记录。</p></div><p class="frequency-footnote">同一天记录两次训练，计为 2 次训练、1 个训练日。无记录不代表休息或未训练。</p></section></template>
<style scoped>
.frequency-card{min-width:0}.frequency-group{display:flex;align-items:center;gap:9px;color:var(--secondary);font-size:12px}.frequency-group select{width:145px}.frequency-toolbar{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;font-size:11px;color:var(--secondary)}.frequency-toolbar b{font-weight:600;color:var(--ink)}.frequency-metric{display:flex;padding:3px;border-radius:8px;background:var(--surface-hover);gap:3px}.frequency-metric button{border:0;border-radius:6px;padding:7px 12px;background:transparent;color:var(--secondary);font-size:12px}.frequency-metric button.active{background:var(--accent-soft);color:var(--primary)}.frequency-rule{font-size:11px;color:var(--secondary);line-height:1.8;margin:12px 0 4px!important}.frequency-chart-scroll{overflow-x:auto;max-width:100%}.frequency-detail{margin-top:14px;border-top:1px solid var(--line);padding-top:16px}.frequency-detail-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.frequency-detail-head>div{display:flex;gap:7px;flex-direction:column}.frequency-detail-head b{font-size:12px;color:var(--ink);font-weight:550}.frequency-detail-head span,.frequency-detail-head>small{font-size:11px;color:var(--secondary)}.frequency-detail-head>small{color:var(--primary)}.frequency-records{max-height:170px;overflow-y:auto}.frequency-records>div{display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--line);font-size:12px}.frequency-records time{font-size:11px;color:var(--secondary);font-variant-numeric:tabular-nums;flex-shrink:0}.frequency-records span{flex:1;overflow-wrap:anywhere}.frequency-records small{font-size:10px;color:var(--secondary);white-space:nowrap}.frequency-footnote{font-size:10px;color:var(--secondary);line-height:1.8;margin-top:14px!important}@media(max-width:760px){.frequency-group{width:100%;justify-content:space-between}.frequency-group select{flex:1;max-width:180px}}
</style>
